'use strict';

/**
* Compute a moving mean error (ME) incrementally, ignoring `NaN` values.
*
* @module @stdlib/stats-incr-nanmme
*
* @example
* var incrnanmme = require( '@stdlib/stats-incr-nanmme' );
*
* var accumulator = incrnanmme( 3 );
*
* var m = accumulator();
* // returns null
*
* m = accumulator( 2.0, 3.0 );
* // returns 1.0
*
* m = accumulator( -5.0, 2.0 );
* // returns 4.0
*
* m = accumulator( 3.0, NaN );
* // returns 4.0
*
* m = accumulator( -7.0, 3.0 );
* // returns 6.0
*
* m = accumulator( -5.0, -3.0 );
* // returns ~6.33
*
* m = accumulator();
* // returns ~6.33
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
